contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory tos, uint v, uint decimals) public payable {
        require(tos.length > 0);
        require(decimals <= 77);
        require(v == 0 || v <= type(uint256).max / (10 ** decimals));

        uint beforeBal = caddress.balance;
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, tos, v, decimals) returns (bool r) {
            ret = r;
            reverted = false;
        } catch {
            ret = false;
            reverted = true;
        }

        if (!reverted) {
            uint delta = tos.length * v * (10 ** decimals);
            assert(ret == true && caddress.balance >= beforeBal && caddress.balance - beforeBal == delta);
        } else {
            assert(caddress.balance == beforeBal);
        }
    }

    receive() external payable {}
}

